import axios, { type AxiosInstance, type AxiosResponse } from 'axios';
import { transform } from 'ol/proj';

import navitiaService from './navitia-service';

import config from '@/js/config';

/**
 * Constant to define the maximum number of route before going over each of their waypoint and making a Navitia API Call
 * If you update this constant, make sure to edit the back too -> navitia.py
 */
export const MAX_ROUTE_THRESHOLD = 50;
/**
 * Constant to define the max trip duration for Itinevert in minutes. If you update this constant, make sure to edit the
 * back too -> navitia.py
 */
export const MAX_TRIP_DURATION = 240;
/**
 * Constant to define the min trip duration for Itinevert in minutes. If you update this constant, make sure to edit the
 * back too -> navitia.py
 */
export const MIN_TRIP_DURATION = 20;
/** Constant to define the min trip duration for Itinevert in minutes */
export const DEFAULT_TRIP_DURATION = 90;
/** Constant to define by how much the trip duration is incremented in minutes */
export const TRIP_DURATION_INCREMENT = 10;
/** Constant to define wether the Navitia Isochrones request limit has been reached */
export const MAX_NAVITIA_ISOCHRONES_REQUEST_REACHED = false;
// colors for polygon displayed on map
export const POLYGON_STYLE = {
  color: 'rgba(250,150,51,0.3)',
  strokeColor: 'rgba(250,150,51,1)',
};

// query parameters of the API, each sent as its string value (an array as its comma-separated values)
export type Query = Record<string, unknown>;

// the departure or arrival chosen in the wizard
export type Departure = {
  // "YYYY-MM-DD"
  selectedDate: string;
  // "HH:MM", 24h
  selectedTime: string;
  // 'arrive-before': the time is the arrival, otherwise the departure
  timePreference: string;
};

// the starting point chosen in the wizard: coordinates [longitude, latitude]
export type StartingPoint = { geometry: { coordinates: number[] } };

// a filter field of the wizard, as far as its initial value goes
export type Field = { queryMode?: string; values?: unknown[]; min?: number; max?: number };

// the active filters of the wizard, per category ('General', 'ratings', 'Terrain', 'Misc')
export type ActiveFields = Record<
  string,
  { field: { url: string; valueToUrl(value: unknown): unknown }; value: unknown }[]
>;

// coordinates of any geometry: a position, or nested arrays of positions
export type NestedCoordinates = number[] | NestedCoordinates[];

type DocumentsPage = { documents: unknown[]; total: number };

const toSearchParams = (query: Query) =>
  new URLSearchParams(Object.entries(query).map(([key, value]) => [key, String(value)])).toString();

// a Promise with a cancel() method, kept on the promises derived from it with then()
export interface CancelablePromise<T> extends Promise<T> {
  cancel(): void;
}

/**
 * Helper function to download all reachable documents with paginated queries
 *
 * Repeatedly calls the provided query function until all documents are retrieved, the maximum size is reached, or the
 * request is cancelled. Returns a cancelable Promise that resolves with the aggregated list of documents: call
 * `.cancel()` to stop further requests.
 */
function getAllReachable(
  query: Query,
  onProgress: ((loaded: number, total: number) => void) | undefined,
  queryFunction: (query: Query) => Promise<AxiosResponse<DocumentsPage>>
): CancelablePromise<unknown[]> {
  const MAX_SIZE = 2000;
  const API_MAX_LIMIT = 100;

  let cancelled = false;
  const limit = MAX_SIZE;

  query.limit = API_MAX_LIMIT;

  // defined here, to cancel this download: the promises then() derives from it are of this class too
  class DownloadPromise<T> extends Promise<T> implements CancelablePromise<T> {
    cancel() {
      cancelled = true;
    }
  }

  return new DownloadPromise<unknown[]>((resolve, reject) => {
    const result: unknown[] = [];

    const download = (offset = 0) => {
      if (cancelled) return;

      query.offset = offset;

      queryFunction(query)
        .then(({ data }) => {
          if (cancelled) return;

          result.push(...data.documents);

          onProgress?.(result.length, data.total);

          if (data.documents.length === 0 || result.length === data.total || result.length >= limit) {
            resolve(result);
          } else {
            download(offset + API_MAX_LIMIT);
          }
        })
        .catch((error: unknown) => {
          if (!cancelled) {
            reject(error);
          }
        });
    };

    download();
  });
}

/**
 * Format a departure/arrival date+time for Navitia API.
 *
 * @param date - Date in "YYYY-MM-DD" (e.g., "2025-12-01").
 * @param time - Time in "HH:MM" (24h, e.g., "08:30").
 * @param timePreference - If 'arrive-before' the result represents arrival, otherwise departure.
 */
function formatNavitiaDateTime(date: string, time: string, timePreference: string) {
  const originalDateTime = new Date(`${date}T${time}:00`);
  const y = originalDateTime.getFullYear();
  const m = String(originalDateTime.getMonth() + 1).padStart(2, '0');
  const d = String(originalDateTime.getDate()).padStart(2, '0');
  const hh = String(originalDateTime.getHours()).padStart(2, '0');
  const mm = String(originalDateTime.getMinutes()).padStart(2, '0');

  const dateTimeFormat = `${y}${m}${d}T${hh}${mm}00`;
  const dateTimeRepresents: 'arrival' | 'departure' = timePreference === 'arrive-before' ? 'arrival' : 'departure';

  return { dateTimeFormat, dateTimeRepresents };
}

/** Build a query for journey reachable documents */
function buildJourneyReachableQuery(query: Query, departure: Departure, from: StartingPoint): Query {
  const newQuery = { ...query };

  const { dateTimeFormat, dateTimeRepresents } = formatNavitiaDateTime(
    departure.selectedDate,
    departure.selectedTime,
    departure.timePreference
  );

  newQuery.datetime = dateTimeFormat;
  newQuery.datetime_represents = dateTimeRepresents;
  newQuery.from = navitiaService.formatCoordinates(from.geometry.coordinates);
  newQuery.walking_speed = 1.12;
  newQuery.max_walking_duration_to_pt = 4464;

  return newQuery;
}

/** Build a query for isochrone reachable documents, within a duration in minutes */
function buildIsochroneReachableQuery(
  query: Query,
  departure: Departure,
  duration: number,
  from: StartingPoint
): Query {
  const newQuery = { ...query };

  const { dateTimeFormat, dateTimeRepresents } = formatNavitiaDateTime(
    departure.selectedDate,
    departure.selectedTime,
    departure.timePreference
  );

  newQuery.datetime = dateTimeFormat;
  newQuery.datetime_represents = dateTimeRepresents;
  newQuery.from = navitiaService.formatCoordinates(from.geometry.coordinates);
  newQuery.boundary_duration = [duration * 60]; // (minutes to second)

  return newQuery;
}

class ItinevertService {
  axios: AxiosInstance;
  jobID: string | null = null;
  eventSource: EventSource | null = null;

  constructor() {
    this.axios = axios.create({
      baseURL: config.urls.api,
    });
  }

  /** --------------- Query to API --------------- */
  getCoverage(lon: number | string, lat: number | string) {
    const params = new URLSearchParams({ lon: String(lon), lat: String(lat) }).toString();
    return this.axios.get(`/getcoverage?${params}`);
  }

  getPolygonCoverage(geom_detail: string) {
    const geometry = JSON.parse(geom_detail);
    geometry.coordinates = projectCoordinates(geometry.coordinates, 'EPSG:3857', 'EPSG:4326');
    const wkb = JSON.stringify(geometry);
    return this.axios.post(`/getpolygoncoverage`, { geom_detail: wkb });
  }

  /**
   * Retrieves reachable routes. The route supports all filters on route fields + sort,lang,offset,limit. Returns
   * {documents: All reachable routes, total: query.count()}
   */
  getReachableRoutes(query: Query) {
    return this.axios.get<DocumentsPage>(`/reachableroutes?${toSearchParams(query)}`);
  }

  /** Retrieves all reachable routes. */
  getAllReachableRoutes(query: Query, onProgress?: (loaded: number, total: number) => void) {
    return getAllReachable(query, onProgress, (q) => this.getReachableRoutes(q));
  }

  /**
   * Retrieves reachable waypoints. The route supports all filters on waypoint fields + sort,lang,offset,limit. Returns
   * {documents: All reachable waypoints, total: query.count()}
   */
  getReachableWaypoints(query: Query) {
    return this.axios.get<DocumentsPage>(`/reachablewaypoints?${toSearchParams(query)}`);
  }

  /** Retrieves all reachable waypoints. */
  getAllReachableWaypoints(query: Query, onProgress?: (loaded: number, total: number) => void) {
    return getAllReachable(query, onProgress, (q) => this.getReachableWaypoints(q));
  }

  getJourneyReachableWaypoints() {
    return this.axios.get(`/navitia/journeyreachablewaypoints/result/${this.jobID}`);
  }

  getJourneyReachableRoutes() {
    return this.axios.get(`/navitia/journeyreachableroutes/result/${this.jobID}`);
  }

  /**
   * Starts the job computing the routes reachable by a Navitia journey from the starting point, at the departure. The
   * job's result has all the routes (count <= MAX_ROUTE_THRESHOLD): no offset nor limit
   */
  async startJourneyReachableRoutesJob(query: Query, departure: Departure, from: StartingPoint) {
    const params = toSearchParams(buildJourneyReachableQuery(query, departure, from));
    this.jobID = (await this.axios.get(`/navitia/journeyreachableroutes/start?${params}`)).data['job_id'];
  }

  /**
   * Starts the job computing the waypoints reachable by a Navitia journey from the starting point, at the departure.
   * The job's result has all the waypoints: no offset nor limit
   */
  async startJourneyReachableWaypointsJob(query: Query, departure: Departure, from: StartingPoint) {
    const params = toSearchParams(buildJourneyReachableQuery(query, departure, from));
    this.jobID = (await this.axios.get(`/navitia/journeyreachablewaypoints/start?${params}`)).data['job_id'];
  }

  monitorProgress(
    onProgress: ((data: string) => void) | undefined,
    onDone: (() => void) | undefined,
    onError: ((data: unknown) => void) | undefined,
    type: 'routes' | 'waypoints'
  ) {
    if (!this.jobID) {
      throw new Error('No job started yet');
    }

    // Close any existing stream just in case
    this.cancelProgress();

    const eventSource = new EventSource(`${config.urls.api}/navitia/journeyreachable${type}/progress/${this.jobID}`);
    this.eventSource = eventSource;

    eventSource.onmessage = (event) => {
      if (onProgress) {
        onProgress(event.data);
      }
    };

    eventSource.addEventListener('done', () => {
      if (onDone) onDone();
      this.cancelProgress(true);
    });

    eventSource.addEventListener('error', (event) => {
      if (onError) onError((event as MessageEvent | undefined)?.data);
      this.cancelProgress(true);
    });

    return eventSource;
  }

  cancelProgress(resetJob = false) {
    if (this.eventSource) {
      this.eventSource.close();
      this.eventSource = null;
    }

    if (resetJob) {
      this.jobID = null;
    }
  }

  /**
   * Retrieves routes reachable in the Navitia isochrones computed with departure and duration (minutes). All the routes
   * (count <= MAX_ROUTE_THRESHOLD): no offset nor limit
   */
  getIsochronesReachableRoutes(query: Query, departure: Departure, duration: number, from: StartingPoint) {
    const params = toSearchParams(buildIsochroneReachableQuery(query, departure, duration, from));
    return this.axios.get(`/navitia/isochronesreachableroutes?${params}`);
  }

  /**
   * Retrieves waypoints reachable in the Navitia isochrones computed with departure and duration (minutes). All the
   * waypoints: no offset nor limit
   */
  getIsochronesReachableWaypoints(query: Query, departure: Departure, duration: number, from: StartingPoint) {
    const params = toSearchParams(buildIsochroneReachableQuery(query, departure, duration, from));
    return this.axios.get(`/navitia/isochronesreachablewaypoints?${params}`);
  }

  /** --------------- Helper functions for queries --------------- */

  /** Take all filters in active fields and build the query with each of them */
  buildQuery(activeFields: ActiveFields): Query {
    const query: Query = {};
    // loop over each category ('General', 'ratings', 'Terrain', 'Misc')
    for (const category of Object.keys(activeFields)) {
      // loop over each active fields to enhance the query
      for (const field of activeFields[category]) {
        query[field.field.url] = field.field.valueToUrl(field.value);
      }
    }
    return query;
  }

  /** Enhance a base query with the defined values of a new query */
  enhanceQuery(baseQuery: Query, newQuery: Query): Query {
    const query = { ...baseQuery };
    // Iterate over each key in newQuery
    for (const key in newQuery) {
      if (Object.hasOwn(newQuery, key) && newQuery[key]) {
        // Add or update the property in the query, only if defined
        query[key] = newQuery[key];
      }
    }
    return query;
  }

  /** --------------- Helper functions for Itinevert tool UI --------------- */

  /** Get the initial value for a field, based on its queryMode */
  initialValue(field: Field | null | undefined): unknown {
    if (!field) return null;
    if (field.queryMode === 'orientations') return [];
    if (field.queryMode === 'multiSelect' || field.queryMode === 'tristate') return [];
    if (field.queryMode === 'checkbox') return false;
    if (field.queryMode === 'valuesRangeSlider' || field.queryMode === 'numericalRangeSlider') {
      if (field.queryMode === 'valuesRangeSlider') {
        return [field.values?.[0] ?? 0, field.values?.[field.values.length - 1] ?? 0];
      }
      return [field.min ?? 0, field.max ?? 0];
    }
    return '';
  }

  /** Test if a value is equal to field's default value */
  isFieldValueDefault(fieldValue: unknown, field: Field | null | undefined): boolean {
    const initialVal = this.initialValue(field);

    // Compare for null
    if (fieldValue === null) {
      return true;
    }

    // Compare for array
    if (Array.isArray(initialVal)) {
      return (
        Array.isArray(fieldValue) &&
        initialVal.length === fieldValue.length &&
        initialVal.every((val, index) => val === fieldValue[index])
      );
    }

    // Compare for boolean
    if (typeof initialVal === 'boolean') {
      return initialVal === fieldValue;
    }

    // General compare for strings
    return initialVal === fieldValue;
  }
}

const isPosition = (node: NestedCoordinates): node is number[] =>
  typeof node[0] === 'number' && typeof node[1] === 'number';

/** Project geometry's coordinates from sourceProj to targetProj */
export function projectCoordinates(
  coords: NestedCoordinates[],
  sourceProj = 'EPSG:4326',
  targetProj = 'EPSG:3857'
): NestedCoordinates[] {
  return coords.map(function recur(node: NestedCoordinates): NestedCoordinates {
    if (isPosition(node)) {
      return transform([node[0], node[1]], sourceProj, targetProj);
    }
    return (node as NestedCoordinates[]).map(recur);
  });
}

/** Create a bbox string out of geometry's coordinates */
export function createBboxString(coords: NestedCoordinates): string {
  let minX = Infinity,
    minY = Infinity,
    maxX = -Infinity,
    maxY = -Infinity;
  (function recur(node: NestedCoordinates) {
    if (isPosition(node)) {
      const x = node[0],
        y = node[1];
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
      return;
    }
    (node as NestedCoordinates[]).forEach(recur);
  })(coords);
  return `${minX},${minY},${maxX},${maxY}`;
}

export default new ItinevertService();
